import 'dart:collection';

void fn0(int V, List<List<int>> adj) {
  List<int> inDegree = List.filled(V, 0);
  for (int i = 0; i < V; i++) {
    for (int node in adj[i]) {
      inDegree[node]++;
    }
  }
  Queue<int> queue = Queue<int>();
  for (int i = 0; i < V; i++) {
    if (inDegree[i] == 0) {
      queue.add(i);
    }
  }
  List<int> result = [];
  while (queue.isNotEmpty) {
    int u = queue.removeFirst();
    result.add(u);
    for (int v in adj[u]) {
      inDegree[v]--;
      if (inDegree[v] == 0) {
        queue.add(v);
      }
    }
  }
  if (result.length != V) {
    print("Graph contains a cycle, topological sort not possible.");
  } else {
    print("Topological Sort:");
    print(result.join(" "));
  }
}

