import 'dart:io';

void topologicalSort(List<List<int>> graph) {
  print("Topological Sort:");
  int v = graph.length;
  List<int> inDegree = List.filled(v, 0);

  for (int i = 0; i < v; i++) {
    for (int neighbor in graph[i]) {
      inDegree[neighbor]++;
    }
  }

  List<int> queue = [];
  for (int i = 0; i < v; i++) {
    if (inDegree[i] == 0) {
      queue.add(i);
    }
  }

  int count = 0;
  List<int> result = [];
  int head = 0;

  while (head < queue.length) {
    int u = queue[head++];
    result.add(u);
    for (int neighbor in graph[u]) {
      inDegree[neighbor]--;
      if (inDegree[neighbor] == 0) {
        queue.add(neighbor);
      }
    }
    count++;
  }

  if (count != v) {
    print("Graph contains a cycle, topological sort not possible.");
    return;
  }

  for (int node in result) {
    print(node);
  }
}

