import 'dart:collection';

void topologicalSort(List<List<int>> graph) {
  int n = graph.length;
  List<int> inDegree = List.filled(n, 0);

  for (int i = 0; i < n; i++) {
    for (int neighbor in graph[i]) {
      inDegree[neighbor]++;
    }
  }

  Queue<int> queue = Queue();
  for (int i = 0; i < n; i++) {
    if (inDegree[i] == 0) {
      queue.add(i);
    }
  }

  List<int> result = [];
  while (queue.isNotEmpty) {
    int u = queue.removeFirst();
    result.add(u);
    for (int v in graph[u]) {
      inDegree[v]--;
      if (inDegree[v] == 0) {
        queue.add(v);
      }
    }
  }

  if (result.length != n) {
    print("Graph contains a cycle, topological sort not possible.");
  } else {
    print("Topological Sort:");
    print(result);
  }
}
```

