void topologicalSort(List<List<int>> graph) {
  int n = graph.length;
  List<int> state = List.filled(n, 0);
  List<int> order = [];
  bool hasCycle = false;

  void dfs(int u) {
    if (hasCycle) return;
    state[u] = 1;
    for (int v in graph[u]) {
      if (state[v] == 1) {
        hasCycle = true;
        return;
      }
      if (state[v] == 0) {
        dfs(v);
      }
    }
    state[u] = 2;
    order.add(u);
  }

  for (int i = 0; i < n; i++) {
    if (state[i] == 0) {
      dfs(i);
    }
  }

  if (hasCycle) {
    print("Graph contains a cycle, topological sort not possible.");
  } else {
    print("Topological Sort:");
    print(order.reversed.toList());
  }
}
```

